      pt: "Caracórum foi no século XIII a lendária capital do Império Mongol sob Ögedei Khan. Hoje, apenas alguns monumentos de pedra, como as famosas tartarugas de pedra, testemunham a sua antiga grandeza.",
      fr: "Karakorum était au XIIIe siècle la légendaire capitale de l'Empire mongol sous Ögedei Khan. Aujourd'hui, seuls quelques monuments de pierre, comme les célèbres tortues de pierre, témoignent de son ancienne grandeur.",
