      es: ["Construido entre 1904 y 1908.", "Funciona hoy como museo de arte religioso.", "Preserva aterradoras máscaras de la danza Tsam.", "Escapó de la destrucción al ser convertido en museo.", "Un fuerte contraste con los modernos rascacielos circundantes."],
      pt: ["Construído entre 1904 e 1908.", "Serve hoje como museu de arte religiosa.", "Preserva máscaras aterrorizantes da dança Tsam.", "Escapou à destruição por ter sido convertido num museu.", "Um forte contraste com os modernos arranha-céus em redor."],
      fr: ["Construit entre 1904 et 1908.", "Sert aujourd'hui de musée d'art religieux.", "Conserve des masques terrifiants de la danse Tsam.", "A échappé à la destruction car il a été transformé en musée.", "Un contraste saisissant avec les gratte-ciel modernes environnants."],
