      es: ["Las piedras datan de los años 732 y 735 d. C.", "Los ejemplos más antiguos conocidos de lengua antiguo turca.", "Junto a las runas también hay grabados textos chinos.", "Fueron descubiertas en 1889 por el investigador ruso Yadrintsev.", "Se consideran un hito de la historia de Asia Central."],
      pt: ["As pedras datam dos anos 732 e 735 d.C.", "Os exemplos mais antigos conhecidos da língua turca antiga.", "Além das runas, também estão gravados textos chineses.", "Foram descobertas em 1889 pelo investigador russo Yadrintsev.", "São consideradas um marco na história da Ásia Central."],
      fr: ["Les stèles datent des années 732 et 735 après J.-C.", "Les plus anciens exemples connus de langue vieux-turque.", "Outre les runes, des textes chinois y sont également gravés.", "Ont été découvertes en 1889 par le chercheur russe Iadrintsev.", "Elles sont considérées comme un jalon de l'histoire de l'Asie centrale."],
